### ✅ **Binary Search Tree Implementation**

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None


class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, data):
        """Inserts a new node with the given data into the BST."""
        if self.root is None:
            self.root = Node(data)
        else:
            current = self.root
            while True:
                if data < current.data:
                    if current.left is None:
                        current.left = Node(data)
                        break
                    else:
                        current = current.left
                else:
                    if current.right is None:
                        current.right = Node(data)
                        break
                    else:
                        current = current.right

    def delete(self, data):
        """Deletes a node with the given data from the BST."""
        current = self.root
        parent = None
        while current and current.data != data:
            parent = current
            if data < current.data:
                current = current.left
            else:
                current = current.right

        if current is None:
            return False  # Data not found

        # Case 1: No children
        if current.left is None and current.right is None:
            if parent is None:
                self.root = None
            elif data < parent.data:
                parent.left = None
            else:
                parent.right = None

        # Case 2: One child
        elif current.left is None:
            if parent is None:
                self.root = current.right
            elif data < parent.data:
                parent.left = current.right
            else:
                parent.right = current.right

        elif current.right is None:
            if parent is None:
                self.root = current.left
            elif data < parent.data:
                parent.left = current.left
            else:
                parent.right = current.left

        # Case 3: Two children
        else:
            # Find the inorder successor (smallest in the right subtree)
            successor_parent = current
            successor = current.right
            while successor.left:
                successor_parent = successor
                successor = successor.left

            # Replace current's data with successor's data
            current.data = successor.data

            # Delete the successor node
            if successor_parent.left == successor:
                successor_parent.left = successor.right
            else:
                successor_parent.right = successor.right

        return True

    def search(self, data):
        """Returns True if the data exists in the BST, False otherwise."""
        current = self.root
        while current:
            if data == current.data:
                return True
            elif data < current.data:
                current = current.left
            else:
                current = current.right
        return False

    def in_order_traversal(self):
        """Returns a list of nodes in in-order traversal (sorted order)."""
        result = []
        def _inorder(node):
            if node:
                _inorder(node.left)
                result.append(node.data)
                _inorder(node.right)
        _inorder(self.root)
        return result


# Example usage
